#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

    /// Given an input vector `a` and a valid index `j < a.len()`,
    /// returns a new vector `result` of the same length as `a`
    /// such that
    ///   - result[j] == 60, and
    ///   - for all k != j, result[k] == a[k].
    #[requires(j < a.len())]
    #[ensures(result.len() == a.len())]
    #[ensures(
        forall|k: usize|
            k < result.len() ==>
                if k == j { result[k] == 60 } else { result[k] == a[k] }
    )]
    fn test_array_elements(a: &Vec<i32>, j: usize) -> (result: Vec<i32>) {
        // Build up `result` element‐by‐element.
        let mut result: Vec<i32> = Vec::with_capacity(a.len());
        let mut i: usize = 0;

        while i < a.len() {
            // Loop invariants:
            //   0 <= i <= a.len()
            //   result.len() == i
            //   for all k < result.len(): result[k] agrees with spec
            invariant(i <= a.len());
            invariant(result.len() == i);
            invariant(
                forall|k: usize|
                    k < result.len() ==>
                        if k == j { result[k] == 60 } else { result[k] == a[k] }
            );
            decreases(a.len() - i);

            if i == j {
                result.push(60);
            } else {
                result.push(a[i]);
            }
            i += 1;
        }

        result
    }
}